export const categories={food:{name:'Alimentation',color:'#d3ddb2',emoji:'🥑'},out:{name:'Sorties & cafés',color:'#edc8ad',emoji:'☕'},transport:{name:'Transport',color:'#c5d9dc',emoji:'🚲'},shopping:{name:'Achats',color:'#d8cce4',emoji:'🛍️'},other:{name:'Autres',color:'#dedccf',emoji:'◌'}};
export const euro=cents=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(cents/100);
export function dateKey(d=new Date()){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
export function shiftDate(day,delta){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+delta);return d.toISOString().slice(0,10)}
export function validDate(day){return typeof day==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(day)&&!Number.isNaN(Date.parse(day+'T12:00:00Z'))&&new Date(day+'T12:00:00Z').toISOString().slice(0,10)===day}
export function validateImport(input){if(!input||input.version!==1||!Array.isArray(input.transactions)||input.transactions.length>5000)throw Error('Format attendu : version 1 et tableau transactions (5 000 maximum).');const ids=new Set();return input.transactions.map(t=>{if(!t||typeof t.id!=='string'||!t.id||t.id.length>160||ids.has(t.id))throw Error('Chaque achat doit avoir un identifiant unique.');ids.add(t.id);if(!validDate(t.date)||typeof t.merchant!=='string'||!t.merchant.trim()||t.merchant.length>200||!Number.isSafeInteger(t.amountCents)||t.amountCents<=0||t.amountCents>100000000||!Object.hasOwn(categories,t.category))throw Error('Date, commerçant, montant positif en centimes ou catégorie invalide.');return {id:t.id,date:t.date,merchant:t.merchant.trim(),amountCents:t.amountCents,category:t.category,status:t.status==='pending'?'pending':'booked',dateBasis:t.dateBasis==='transaction'?'transaction':'booking'};})}
export function demoData(today){const rows=[['Bio c’ Bon',1280,'food'],['Café du coin',350,'out'],['Boulangerie',590,'food'],['Métro',255,'transport'],['Librairie',1890,'shopping']];const list=[];for(let offset=-6;offset<=0;offset++){const day=shiftDate(today,offset);rows.slice(0,offset===0?5:2+(Math.abs(offset)%3)).forEach((r,i)=>list.push({id:`demo-${day}-${i}`,date:day,merchant:r[0],amountCents:r[1]+(offset===0?0:Math.abs(offset)*20),category:r[2],status:'booked',dateBasis:'transaction'}));}return list}
// Fixed monetary scale: r² = cents / 0.18. Packing only changes position, never radius.
export function pack(items){const placed=[];for(const t of [...items].sort((a,b)=>b.amountCents-a.amountCents||a.id.localeCompare(b.id))){const r=Math.sqrt(t.amountCents/0.18);let x=0,y=0;let found=false;for(let step=0;step<30000;step++){const angle=step*2.3999632297,dist=2*Math.sqrt(step);x=Math.cos(angle)*dist;y=Math.sin(angle)*dist;if(placed.every(p=>Math.hypot(x-p.x,y-p.y)>=r+p.r+3)){found=true;break}}if(!found){x=Math.max(0,...placed.map(p=>p.x+p.r))+r+3;y=0}placed.push({...t,x,y,r})}return placed}
export function extent(packs){let w=230,h=180;for(const pack of packs)for(const p of pack){w=Math.max(w,Math.abs(p.x)+p.r+20);h=Math.max(h,Math.abs(p.y)+p.r+20)}return [-w,-h,2*w,2*h].join(' ')}
